#!/usr/bin/env python3
"""Build complete static HTML for the fictional Lattice Commercial Electric demo."""
from html import escape
from pathlib import Path
import shutil

ROOT = Path(__file__).parent
OUT = ROOT / 'dist'
DOMAIN = 'https://lattice-commercial-electric.vercel.app'
NAV = [('/', 'Home'), ('/services/', 'Services'), ('/our-process/', 'Our Process'), ('/project-preview/', 'Project Preview')]
PAGES = {
    '/': ('Commercial Electrical Contracting | Lattice Commercial Electric Demo', 'A fictional commercial electrical contracting website for tenant improvements, distribution, lighting and facility projects.', 'home'),
    '/services/': ('Electrical Services | Lattice Commercial Electric Demo', 'Explore illustrative commercial electrical project, facility, lighting and distribution pathways.', 'services'),
    '/our-process/': ('Our Process | Lattice Commercial Electric Demo', 'A clear example process for scope, safety and the next conversation about commercial electrical work.', 'process'),
    '/project-preview/': ('Project Preview | Lattice Commercial Electric Demo', 'Preview a local-only electrical project inquiry. No request is transmitted or booked.', 'preview'),
}

def photo(name, alt, w, h, eager=False):
    return f'<img src="/assets/{name}.webp" width="{w}" height="{h}" alt="{escape(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async"{" fetchpriority=\"high\"" if eager else ""}>'

def button(text, href='/project-preview/', kind='primary'):
    return f'<a class="button {kind}" href="{href}">{escape(text)}</a>'

def shell(route, body):
    title, desc, _ = PAGES[route]
    canonical = DOMAIN + route
    nav = ''.join(f'<a href="{href}"{" aria-current=\"page\"" if href == route else ""}>{label}</a>' for href, label in NAV)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#233d3d"><meta name="robots" content="noindex,nofollow"><title>{escape(title)}</title><meta name="description" content="{escape(desc)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{DOMAIN}/assets/hero.webp"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/styles.css"><script src="/script.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><div class="demo">Fictional FireWorks website demo · Illustrative photographs · No requests are sent or booked</div><header class="header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Lattice Commercial Electric home"><span class="brand-mark" aria-hidden="true">L</span><span>LATTICE<small>ELECTRIC · DEMO</small></span></a><button id="menu-toggle" class="menu-toggle" aria-expanded="false" aria-controls="primary-nav" type="button">Menu</button><nav id="primary-nav" class="nav" aria-label="Main navigation">{nav}<a class="nav-cta" href="/project-preview/">Plan a project</a></nav></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap footer-grid"><div><strong>LATTICE ELECTRIC</strong><p>A fictional commercial electrical contracting concept. No actual company, crew, job or availability is represented.</p></div><div><strong>Explore</strong>{nav}</div><div><strong>Demo safety</strong><p>Inquiry fields validate only in this browser. Nothing is sent, stored, monitored, scheduled or paid.</p></div></div></footer></body></html>'''

home = f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">COMMERCIAL ELECTRICAL · FICTIONAL DEMO</p><h1>Build the space. Keep it moving.</h1><p class="lede">Electrical planning for changing workplaces, tenant improvements and facility needs begins with a clear scope and the right people at the table.</p><div class="actions">{button('Preview a project inquiry')}{button('Explore capabilities','/services/','outline')}</div><p class="fine">No bid, response time or service availability is promised in this demo.</p></div><figure class="hero-image">{photo('hero','Electrician surveying closed switchgear in a commercial electrical room; illustrative image',1600,819,True)}<figcaption>Illustrative generated imagery</figcaption></figure></section>
<section class="service-ribbon"><div class="wrap"><span>Tenant improvements</span><span>Power distribution</span><span>Lighting systems</span><span>Facility upgrades</span></div></section>
<section class="section wrap split"><div class="image"><figure>{photo('testing','Electrician inspecting closed industrial electrical equipment in a warehouse; illustrative image',1536,1024)}<figcaption>Illustrative inspection scene</figcaption></figure></div><div class="copy"><p class="eyebrow">START WITH THE SCOPE</p><h2>Give facilities teams a clear first step.</h2><p>Capture the property type, project stage, operational constraints and point of contact. A real contractor can evaluate capacity, code requirements and safe work methods after an approved intake.</p><ul><li>Tenant and facility project paths</li><li>Project timing and site constraints</li><li>Room for drawings and bid documents after secure integration</li></ul>{button('Preview the inquiry')}</div></section>
<section class="statement"><div class="wrap"><p class="eyebrow">LIGHTING FOR WORKING SPACES</p><h2>Spaces change. Lighting should keep pace.</h2><p>Show the planning conversation around office lighting, controls and phased improvements. Replace this illustrative setting with verified project photography before a real launch.</p>{button('Explore capabilities','/services/')}</div>{photo('lighting','Linear lighting in a modern commercial office corridor; illustrative image',1600,900)}</section>
<section class="section wrap split flip"><div class="image"><figure>{photo('planning','Commercial electricians reviewing blank project drawings at a construction site; illustrative image',1536,1024)}<figcaption>Illustrative planning scene</figcaption></figure></div><div class="copy"><p class="eyebrow">COORDINATE BEFORE MOBILIZATION</p><h2>A more useful project conversation.</h2><p>Facility teams, general contractors and tenants need a shared understanding of scope, access, sequencing and decision points. The real provider confirms permits, staffing, timeline and pricing.</p>{button('See the process','/our-process/','dark')}</div></section>
<section class="slider-section" aria-label="Commercial electrical planning examples"><div class="wrap slider-top"><div><p class="eyebrow">A CLOSER LOOK</p><h2>Different buildings. Different priorities.</h2></div><div class="slider-controls"><button type="button" data-prev aria-label="Previous example">Previous</button><button type="button" data-next aria-label="Next example">Next</button></div></div><div class="wrap slider" tabindex="0" aria-roledescription="carousel" aria-label="Commercial electrical examples"><figure class="slide" data-slide>{photo('ev','High-bay lights and conduit in an illustrative warehouse interior',1600,900)}<figcaption><strong>Warehouse lighting</strong><span>Illustrative facility conversation, not a completed installation.</span></figcaption></figure><figure class="slide" data-slide hidden>{photo('lighting','Modern office corridor with linear lighting; illustrative image',1600,900)}<figcaption><strong>Tenant improvement</strong><span>Illustrative workspace, not a client project.</span></figcaption></figure></div><p class="wrap slider-status" data-slider-status aria-live="polite">Example 1 of 2</p></section>
<section class="section wrap proof"><div><p class="eyebrow">EVIDENCE, WHEN VERIFIED</p><h2>Show how the work was coordinated.</h2><p>A real contractor can add approved scopes, permissions, project photos and sourced customer feedback here.</p></div><div class="proof-slots"><article><small>SAMPLE CASE-STUDY SLOT</small><h3>Project scope and sequencing</h3><p>Add approved building type, scope, coordination notes and client-approved outcome.</p></article><article><small>SAMPLE REVIEW SLOT</small><h3>Facility team perspective</h3><p>Add a sourced review only with permission and the exact approved wording.</p></article></div></section><section class="end-cta"><div class="wrap"><h2>Have a project to discuss?</h2><p>Try the local-only commercial inquiry preview. No bid request is transmitted.</p>{button('Preview a project inquiry')}</div></section>'''

services = f'''<section class="page-head wrap"><p class="eyebrow">CAPABILITIES · SAMPLE CONTENT</p><h1>Electrical scope for working spaces.</h1><p>Illustrative commercial project routes. A real contractor must verify its actual trades, service boundaries, staffing and qualifications.</p>{button('Preview a project inquiry')}</section><section class="section wrap service-list"><article><div><p class="eyebrow">01 / CONSTRUCTION</p><h2>Tenant improvements</h2><p>Office build-outs, reconfigurations and phased occupancy require coordination with the owner, tenant and general contractor.</p>{button('Describe the project')}</div>{photo('planning','Illustrative commercial electricians reviewing plans at a worksite',1536,1024)}</article><article><div><p class="eyebrow">02 / INFRASTRUCTURE</p><h2>Distribution and equipment</h2><p>Discuss existing conditions, capacity questions, equipment and site access for an appropriate on-site assessment.</p>{button('Plan an assessment')}</div>{photo('testing','Illustrative inspection of closed commercial distribution equipment',1536,1024)}</article><article><div><p class="eyebrow">03 / FACILITIES</p><h2>Lighting and facility upgrades</h2><p>Outline operating hours, workspace use and phasing questions before any product or timeline recommendation.</p>{button('Talk through the scope')}</div>{photo('ev','Illustrative high-bay lighting and conduit in a warehouse',1600,900)}</article></section>'''

process = f'''<section class="page-head wrap"><p class="eyebrow">PROCESS · SAMPLE FRAMEWORK</p><h1>Scope, sequence, then execution.</h1><p>A commercial project website should make the coordination steps clear without promising a bid, schedule or outcome in a demo.</p>{button('Preview the inquiry')}</section><section class="section wrap process"><article><span>01</span><h2>Describe the facility</h2><p>Share building type, project stage, operating constraints and key contacts. This demo stays in your browser.</p></article><article><span>02</span><h2>Review conditions</h2><p>A real contractor assesses drawings, site conditions, safety, code, access and capacity as appropriate.</p></article><article><span>03</span><h2>Align the scope</h2><p>Only verified client estimates, terms, staffing, timing and service areas belong on a launched site.</p></article></section><section class="section wrap split"><div class="image">{photo('planning','Illustrative commercial electrical planning conversation at a jobsite',1536,1024)}</div><div class="copy"><p class="eyebrow">EVIDENCE BUILDS TRUST</p><h2>Make every claim traceable.</h2><p>Replace sample case studies and reviews with approved project details and source links. License, insurance, qualifications and operational claims need verification.</p>{button('Try the inquiry preview')}</div></section>'''

preview = '''<section class="page-head wrap"><p class="eyebrow">LOCAL-ONLY INQUIRY PREVIEW</p><h1>Tell us about the facility.</h1><p>Preview the information a commercial contractor might request. No bid request or appointment is created.</p></section><section class="section wrap form-layout"><div><h2>Start with a clear scope.</h2><p>Building type, work category, timing and access constraints help frame a useful first conversation. Do not enter confidential details in this demo.</p><div class="safety"><strong>Immediate electrical hazard?</strong><p>Move away from fire, smoke, arcing, exposed wiring or shock risk. Contact emergency services or the responsible utility as appropriate. This website is not monitored.</p></div></div><form id="demo-form"><label>Building type<select required name="building"><option value="">Choose a type</option><option>Office or tenant space</option><option>Retail or hospitality</option><option>Warehouse or industrial</option><option>Other commercial</option></select></label><label>Project ZIP or community<input name="area" required minlength="2" maxlength="80" autocomplete="off"></label><label>Work category<select required name="category"><option value="">Choose a category</option><option>Tenant improvement</option><option>Distribution or equipment</option><option>Lighting or controls</option><option>Facility maintenance planning</option><option>Other</option></select></label><label>Project stage<select required name="stage"><option value="">Choose a stage</option><option>Early planning</option><option>Drawings in progress</option><option>Ready to discuss scope</option></select></label><label>Scope and site constraints<textarea name="details" required minlength="15" maxlength="1000" placeholder="Describe the space, desired work and any operating constraints"></textarea></label><button type="submit" class="button primary">Check demo inquiry</button><p class="fine">No transmission, storage, booking, dispatch or payment takes place.</p><p id="form-status" role="status" aria-live="polite"></p></form></section>'''

def build():
    if OUT.exists(): shutil.rmtree(OUT)
    OUT.mkdir()
    shutil.copytree(ROOT / 'assets', OUT / 'assets')
    for static in ('styles.css', 'script.js', 'robots.txt'):
        shutil.copy2(ROOT / static, OUT / static)
    bodies = {'home':home, 'services':services, 'process':process, 'preview':preview}
    for route, (_, _, key) in PAGES.items():
        dest = OUT / route.lstrip('/') / 'index.html'
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(shell(route,bodies[key]))
    (OUT / '404.html').write_text(shell('/', '<section class="page-head wrap"><h1>Page not found.</h1><p>The requested page does not exist in this demo.</p>'+button('Return home','/')+'</section>').replace('<title>'+escape(PAGES['/'][0])+'</title>','<title>Page Not Found | Lattice Commercial Electric Demo</title>'))
    (OUT / 'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{DOMAIN}{route}</loc></url>' for route in PAGES)+'</urlset>')
    (OUT / 'vercel.json').write_text('{"cleanUrls":true,"trailingSlash":true}')

if __name__ == '__main__': build()
